<template>
  <section class="prc" dir="rtl">
    <header><div><h4>قالب گزارش شخصی</h4><small>ستون‌هایی که {{ resourceName }} در ریز کارکرد خود می‌بیند.</small></div><button type="button" @click="open=!open">{{ open?'بستن':'تنظیم ستون‌ها' }}</button></header>
    <div v-if="open" class="prc-body">
      <div class="prc-picker"><label v-for="column in options" :key="column.key" :class="{on:selected.includes(column.key)}"><input type="checkbox" :checked="selected.includes(column.key)" @change="toggle(column.key)"><span>{{ column.label }}</span></label></div>
      <div class="prc-order"><strong>ترتیب نمایش</strong><div v-for="(key,index) in selected" :key="key"><span>{{ label(key) }}</span><button type="button" :disabled="index===0" @click="move(index,-1)">↑</button><button type="button" :disabled="index===selected.length-1" @click="move(index,1)">↓</button><button type="button" @click="toggle(key)">×</button></div></div>
      <div class="prc-copy"><label>کپی قالب از<select v-model="copyKey"><option value="">انتخاب پزشک یا پرسنل</option><option v-for="item in resources" :key="`${item.type}-${item.id}`" :value="`${item.type}-${item.id}`">{{ item.name }} ({{ item.type==='doctor'?'پزشک':'پرسنل' }})</option></select></label><button type="button" :disabled="!copyKey" @click="copyFrom">کپی برای این شخص</button></div>
      <details class="prc-bulk"><summary>اعمال برای چند شخص انتخابی</summary><div><label v-for="item in resources" :key="`target-${item.type}-${item.id}`"><input v-model="bulkTargets" type="checkbox" :value="`${item.type}-${item.id}`">{{ item.name }} ({{ item.type==='doctor'?'پزشک':'پرسنل' }})</label></div></details>
      <footer><button type="button" :disabled="saving||!selected.length" @click="save('resource')">ذخیره برای این شخص</button><button type="button" :disabled="saving||!selected.length||!bulkTargets.length" @click="save('selected')">اعمال برای انتخاب‌شده‌ها</button><button type="button" :disabled="saving||!selected.length" @click="save(resourceType==='doctor'?'all_doctors':'all_staff')">اعمال برای همه {{ resourceType==='doctor'?'پزشکان':'پرسنل' }}</button><button class="ghost" type="button" :disabled="saving||!selected.length" @click="save('default')">ثبت به‌عنوان پیش‌فرض</button></footer>
    </div>
  </section>
</template>
<script>
import axios from 'axios';import Swal from 'sweetalert2';
export default{name:'PersonalReportColumns',props:{resourceType:{type:String,required:true},resourceId:{type:Number,required:true},resourceName:{type:String,default:''},currentColumns:{type:Array,default:()=>[]},startOpen:{type:Boolean,default:false}},data(){return{open:this.startOpen,loading:false,saving:false,options:[],resources:[],defaults:[],selected:[],copyKey:'',bulkTargets:[]}},watch:{currentColumns:{immediate:true,handler(v){if(Array.isArray(v)&&v.length)this.selected=[...v]}},startOpen(v){if(v)this.open=true}},mounted(){this.load()},methods:{async load(){try{const d=(await axios.get('/api/employee-portal/report-columns')).data;this.options=d.columns||[];this.resources=d.resources||[];this.defaults=d.default_columns||[];if(!this.selected.length)this.selected=[...(this.defaults||[])]}catch{}},label(k){return this.options.find(i=>i.key===k)?.label||k},toggle(k){this.selected=this.selected.includes(k)?this.selected.filter(i=>i!==k):[...this.selected,k]},move(i,d){const n=[...this.selected],[x]=n.splice(i,1);n.splice(i+d,0,x);this.selected=n},copyFrom(){const [type,id]=this.copyKey.split('-');const r=this.resources.find(i=>i.type===type&&Number(i.id)===Number(id));this.selected=[...(r?.columns?.length?r.columns:this.defaults)]},async save(scope){this.saving=true;try{const targets=this.bulkTargets.map(key=>{const[type,id]=key.split('-');return{type,id:Number(id)}});await axios.put('/api/employee-portal/report-columns',{resource_type:this.resourceType,resource_id:this.resourceId,columns:this.selected,scope,targets});Swal.fire({icon:'success',title:'قالب گزارش ذخیره شد',timer:1300,showConfirmButton:false});this.$emit('saved',this.selected)}catch(e){Swal.fire({icon:'error',title:e.response?.data?.message||'ذخیره قالب انجام نشد.'})}finally{this.saving=false}}}}
</script>
<style scoped>
.prc{padding:15px;border:1px solid #dfe8f2;border-radius:16px;background:#f9fbfe}.prc>header{display:flex;justify-content:space-between;align-items:center}.prc h4{margin:0 0 3px}.prc small{color:#64748b}.prc>header button,.prc footer button,.prc-copy button{padding:8px 12px;border:0;border-radius:9px;background:#2563eb;color:#fff;font-family:inherit}.prc-body{display:grid;gap:14px;margin-top:15px}.prc-picker{display:flex;flex-wrap:wrap;gap:7px}.prc-picker label{padding:7px 9px;border:1px solid #dce5ef;border-radius:9px;background:#fff}.prc-picker label.on{border-color:#2563eb;background:#eff6ff;color:#1d4ed8}.prc-picker input{margin-left:5px}.prc-order{display:grid;gap:6px}.prc-order>div{display:grid;grid-template-columns:1fr 32px 32px 32px;gap:5px;padding:7px;border-radius:9px;background:#fff}.prc-order button{border:0;border-radius:7px;background:#e9eff7}.prc-copy{display:flex;align-items:end;gap:8px}.prc-copy label{flex:1;display:grid;gap:5px}.prc-copy select{padding:9px;border:1px solid #d6e0eb;border-radius:9px}.prc-bulk{padding:10px;border-radius:10px;background:#fff}.prc-bulk summary{cursor:pointer;font-weight:800}.prc-bulk>div{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:7px;margin-top:10px}.prc-bulk label{padding:7px;border:1px solid #e2e8f0;border-radius:8px}.prc-bulk input{margin-left:6px}.prc footer{display:flex;flex-wrap:wrap;gap:7px}.prc footer .ghost{background:#e2e8f0;color:#475569}
</style>
